#include <hip/hip_runtime.h>

#define M_BLK 64
#define N_BLK 64
#define K_BLK 16

__global__ void bmm_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, 
                           int m, int n, int k) {

    int batch_idx = blockIdx.z;
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Offsets for batch
    long long batch_offset_A = (long long)batch_idx * m * k;
    long long batch_offset_B = (long long)batch_idx * k * n;
    long long batch_offset_C = (long long)batch_idx * m * n;

    const float* A_ptr = A + batch_offset_A;
    const float* B_ptr = B + batch_offset_B;
    float* C_ptr = C + batch_offset_C;

    int tid = threadIdx.y * blockDim.x + threadIdx.x;
    int tx = threadIdx.x; // 0..15
    int ty = threadIdx.y; // 0..15

    __shared__ float As[M_BLK][K_BLK];
    __shared__ float Bs[K_BLK][N_BLK];

    float c_reg[4][4];
    #pragma unroll
    for(int i=0; i<4; ++i) {
        #pragma unroll
        for(int j=0; j<4; ++j) {
            c_reg[i][j] = 0.0f;
        }
    }

    // Loading indices
    // A: 64x16. 256 threads. Each loads 1 float4 (4 floats).
    int load_a_row = tid / 4;        // 0..63
    int load_a_col = (tid % 4) * 4;  // 0, 4, 8, 12

    // B: 16x64. 256 threads. Each loads 1 float4.
    int load_b_row = tid / 16;       // 0..15
    int load_b_col = (tid % 16) * 4; // 0, 4..60

    // Initial pointers
    // A ptr at (by*M_BLK + load_a_row, load_a_col)
    const float* A_tile = A_ptr + (by * M_BLK + load_a_row) * k + load_a_col;
    // B ptr at (load_b_row, bx*N_BLK + load_b_col)
    const float* B_tile = B_ptr + (load_b_row) * n + (bx * N_BLK + load_b_col);

    for (int k_idx = 0; k_idx < k; k_idx += K_BLK) {

        // Load A
        float4 a_val = *reinterpret_cast<const float4*>(A_tile);
        As[load_a_row][load_a_col + 0] = a_val.x;
        As[load_a_row][load_a_col + 1] = a_val.y;
        As[load_a_row][load_a_col + 2] = a_val.z;
        As[load_a_row][load_a_col + 3] = a_val.w;

        // Load B
        float4 b_val = *reinterpret_cast<const float4*>(B_tile);
        Bs[load_b_row][load_b_col + 0] = b_val.x;
        Bs[load_b_row][load_b_col + 1] = b_val.y;
        Bs[load_b_row][load_b_col + 2] = b_val.z;
        Bs[load_b_row][load_b_col + 3] = b_val.w;

        __syncthreads();

        // Compute
        #pragma unroll
        for (int kk = 0; kk < K_BLK; ++kk) {
            float a_reg_k[4];
            float b_reg_k[4];

            #pragma unroll
            for(int i=0; i<4; ++i) {
                a_reg_k[i] = As[ty + i * 16][kk];
            }
            #pragma unroll
            for(int j=0; j<4; ++j) {
                b_reg_k[j] = Bs[kk][tx + j * 16];
            }

            #pragma unroll
            for(int i=0; i<4; ++i) {
                #pragma unroll
                for(int j=0; j<4; ++j) {
                    c_reg[i][j] += a_reg_k[i] * b_reg_k[j];
                }
            }
        }

        __syncthreads();

        // Update pointers
        A_tile += K_BLK;
        B_tile += K_BLK * n;
    }

    // Store results
    int row_start = by * M_BLK + ty;
    int col_start = bx * N_BLK + tx;

    #pragma unroll
    for(int i=0; i<4; ++i) {
        int r = row_start + i * 16;
        #pragma unroll
        for(int j=0; j<4; ++j) {
            int c = col_start + j * 16;
            if (r < m && c < n) {
                C_ptr[r * n + c] = c_reg[i][j];
            }
        }
    }
}

torch::Tensor bmm_hip(torch::Tensor A, torch::Tensor B) {
    int batch_size = A.size(0);
    int m = A.size(1);
    int k = A.size(2);
    int n = B.size(2);

    auto C = torch::empty({batch_size, m, n}, A.options());

    dim3 block(16, 16);
    dim3 grid((n + 63) / 64, (m + 63) / 64, batch_size);

    bmm_kernel<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(),
                                m, n, k);

    return C;
